      "Accounts and Brokers": "\u0627\u0644\u062D\u0633\u0627\u0628\u0627\u062A \u0648\u0627\u0644\u0648\u0633\u0637\u0627\u0621",
      "Settings and Personalization": "\u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0648\u0627\u0644\u062A\u062E\u0635\u064A\u0635",
