      "Enter your full name": "\u0623\u062F\u062E\u0644 \u0627\u0633\u0645\u0643 \u0627\u0644\u0643\u0627\u0645\u0644",
      "Enter your email address": "\u0623\u062F\u062E\u0644 \u0639\u0646\u0648\u0627\u0646 \u0628\u0631\u064A\u062F\u0643 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A",
      Category: "\u0627\u0644\u0641\u0626\u0629",
      "Select Category": "\u0627\u062E\u062A\u0631 \u0627\u0644\u0641\u0626\u0629",
