      Holiday: "\u0639\u0637\u0644\u0629",
      "Unable to load events": "\u062A\u0639\u0630\u0651\u0631 \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u0623\u062D\u062F\u0627\u062B",
      "Check your internet connection and try again": "\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u062A\u0635\u0627\u0644\u0643 \u0628\u0627\u0644\u0625\u0646\u062A\u0631\u0646\u062A \u0648\u062D\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649",
      Retry: "\u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0645\u062D\u0627\u0648\u0644\u0629",
      "No events found": "\u0644\u0645 \u064A\u062A\u0645 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0623\u062D\u062F\u0627\u062B",
      "Try adjusting your filters or date range": "\u062C\u0631\u0651\u0628 \u062A\u0639\u062F\u064A\u0644 \u0627\u0644\u0641\u0644\u0627\u062A\u0631 \u0623\u0648 \u0646\u0637\u0627\u0642 \u0627\u0644\u062A\u0627\u0631\u064A\u062E",
      "Reset All Filters": "\u0625\u0639\u0627\u062F\u0629 \u062A\u0639\u064A\u064A\u0646 \u0643\u0644 \u0627\u0644\u0641\u0644\u0627\u062A\u0631",
      events: "\u0623\u062D\u062F\u0627\u062B",
      "Event Filters": "\u0641\u0644\u0627\u062A\u0631 \u0627\u0644\u0623\u062D\u062F\u0627\u062B",
      "Customize which events appear": "\u062E\u0635\u0651\u0635 \u0627\u0644\u0623\u062D\u062F\u0627\u062B \u0627\u0644\u062A\u064A \u062A\u0638\u0647\u0631",
      "IMPACT LEVEL": "\u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u062A\u0623\u062B\u064A\u0631",
