      "Show Bank Holidays": "\u0625\u0638\u0647\u0627\u0631 \u0627\u0644\u0639\u0637\u0644\u0627\u062A \u0627\u0644\u0645\u0635\u0631\u0641\u064A\u0629",
      "Apply Filters": "\u062A\u0637\u0628\u064A\u0642 \u0627\u0644\u0641\u0644\u0627\u062A\u0631",
