      "Messages and News": "\u09AC\u09BE\u09B0\u09CD\u09A4\u09BE \u0993 \u09B8\u0982\u09AC\u09BE\u09A6",
      "Accounts and Brokers": "\u0985\u09CD\u09AF\u09BE\u0995\u09BE\u0989\u09A8\u09CD\u099F \u0993 \u09AC\u09CD\u09B0\u09CB\u0995\u09BE\u09B0",
      "Settings and Personalization": "\u09B8\u09C7\u099F\u09BF\u0982\u09B8 \u0993 \u09AC\u09CD\u09AF\u0995\u09CD\u09A4\u09BF\u0997\u09A4\u0995\u09B0\u09A3",
